def _norm(t):
    from .activities import norm

    return norm(t)


def search(q, mods, n=5):
    """Local search: the topics whose words are in the question (works with no internet)."""
    nq = _norm(q)
    words = [w for w in nq.split() if len(w) > 1]
    scored = []
    for title, kw, url, mod, ans in TOPICS:
        hay = _norm(title + " " + kw)
        sc = sum(len(w) for w in words if w in hay) + sum(3 for w in _norm(title).split() if len(w) > 2 and w in nq)
        if sc:
            scored.append((sc, dict(t=title, a=ans, url=url, ok=mod is None or mod in mods, mod=mod)))
    scored.sort(key=lambda x: -x[0])
    return [d for _, d in scored[:n]]


def pages(mods, owner):
    owner_only = {"/ui/shop/money/", "/ui/shop/profit/", "/ui/shop/settings/", "/ui/shop/activity/", "/ui/shop/upgrade/", "/ui/shop/branches/", "/ui/vouchers/"}
    return [dict(name=n, url=u) for n, u, m in PAGES if (m is None or m in mods) and (owner or u not in owner_only)]


def local_answer(q, mods):
    found = search(q, mods, 3)
    if not found:
        return dict(answer="لم أجد نتيجة لهذا البحث. جرّب كلمة أخرى (مثلًا: مرتجع، جرد، مصروف، تقرير)، أو تواصل مع Trio 01008030459.", links=[])
    best = found[0]
    if not best["ok"]:
        return dict(answer=f"«{best['t']}» غير متاحة لنوع نشاطك — تواصل مع Trio إن احتجت إليها: 01008030459.", links=["/ui/shop/upgrade/"])
    more = [f["t"] for f in found[1:] if f["ok"]]
    return dict(answer=best["a"] + ("\n\nيمكن أيضًا: " + "، ".join(more) if more else ""), links=[best["url"]])


def names_of(mods):
    return [M.MODULES[m][0] for m in mods if m in M.MODULES]
